            <div class="modal-head"><div><h3>Feed Thumbnail Library</h3><p class="hint" style="margin:3px 0 0">Choose an image from {{ $currentAppName }} or shared media.</p></div><button type="button" class="btn small" data-close-media>Close</button></div>
            <div class="media-search"><input class="input" type="search" data-media-search placeholder="Search thumbnails, labels, buckets..."></div>
            <div class="asset-grid" data-media-grid>
                @forelse($mediaAssets as $asset)
                    <button type="button" class="asset" data-asset data-url="{{ $asset['url'] }}" data-label="{{ e($asset['label']) }}" data-bucket="{{ e($asset['bucket']) }}"><img src="{{ $asset['url'] }}" alt=""><div><strong>{{ $asset['label'] }}</strong><span>{{ $asset['bucket'] }}</span></div></button>
                @empty
                    <div class="empty" style="grid-column:1/-1">No image assets found yet. Use Quick Upload Thumbnail or open the full Media Library.</div>
                @endforelse
            </div>
            <div class="footer-actions"><div class="actions" style="justify-content:flex-end"><a class="btn" target="_blank" href="{{ url('/admin/media-library') }}">Open Full Media Library</a><button type="button" class="btn primary" data-close-media>Done</button></div></div>
        </div>
    </div>
</div>
<script>
(function(){
 const root=document.querySelector('[data-feed-editor]'); if(!root)return;
 const tabs=[...root.querySelectorAll('[data-tab]')], panes=[...root.querySelectorAll('[data-pane]')], hidden=document.getElementById('activeTabInput');
 function selectTab(name,push=true){tabs.forEach(t=>t.classList.toggle('active',t.dataset.tab===name));panes.forEach(p=>p.classList.toggle('active',p.dataset.pane===name));if(hidden)hidden.value=name;try{localStorage.setItem('feedEditorTab',name)}catch(e){}if(push){history.replaceState(null,'',location.pathname+'?tab='+encodeURIComponent(name));}}
 const urlTab=new URLSearchParams(location.search).get('tab');let saved=null;try{saved=localStorage.getItem('feedEditorTab')}catch(e){}selectTab(urlTab||saved||'setup',false);tabs.forEach(t=>t.addEventListener('click',()=>selectTab(t.dataset.tab)));
 const titleIn=root.querySelector('[data-preview-title]'),titleOut=root.querySelector('[data-preview-title-out]'),excerptIn=root.querySelector('[data-preview-excerpt]'),excerptOut=root.querySelector('[data-preview-excerpt-out]'),ctaIn=root.querySelector('[data-preview-cta]'),ctaOut=root.querySelector('[data-preview-cta-out]'),imgIn=root.querySelector('[data-preview-image]'),thumb=root.querySelector('[data-preview-thumb]'),typeOut=root.querySelector('[data-preview-type]'),bucket=document.getElementById('bucketSelect'),selImg=root.querySelector('[data-selected-image]'),selUrl=root.querySelector('[data-selected-url]');
 function safe(v){return String(v||'').replace(/"/g,'&quot;')}
 function sync(){const img=imgIn&&imgIn.value.trim(); if(titleOut)titleOut.textContent=(titleIn&&titleIn.value.trim())||'Your feed post title appears here'; if(excerptOut)excerptOut.textContent=(excerptIn&&excerptIn.value.trim())||'A short summary helps users quickly understand this community update.'; if(ctaOut)ctaOut.textContent=(ctaIn&&ctaIn.value.trim())||'Open'; if(thumb)thumb.innerHTML=img?'<img src="'+safe(img)+'" alt="">':'<span>FEED</span>'; if(selImg)selImg.innerHTML=img?'<img src="'+safe(img)+'" alt="">':'<span>No Image</span>'; if(selUrl)selUrl.textContent=img||'No thumbnail selected yet.';}
 [titleIn,excerptIn,ctaIn,imgIn].forEach(el=>el&&el.addEventListener('input',sync)); sync();
 root.querySelectorAll('[data-choice]').forEach(ch=>{ch.addEventListener('click',()=>{root.querySelectorAll('[data-choice]').forEach(x=>x.classList.remove('active'));ch.classList.add('active');const radio=ch.querySelector('input[type=radio]');if(radio){radio.checked=true;if(typeOut)typeOut.textContent=ch.querySelector('strong').textContent;}if(bucket&&ch.dataset.bucket)bucket.value=ch.dataset.bucket;});});
 const modal=root.querySelector('[data-media-modal]'), open=root.querySelector('[data-open-media]'), search=root.querySelector('[data-media-search]');
 function openModal(){if(modal){modal.classList.add('open');document.body.style.overflow='hidden';setTimeout(()=>search&&search.focus(),60)}}
 function closeModal(){if(modal){modal.classList.remove('open');document.body.style.overflow=''}}
 open&&open.addEventListener('click',openModal); root.querySelectorAll('[data-close-media]').forEach(b=>b.addEventListener('click',closeModal)); modal&&modal.addEventListener('click',e=>{if(e.target===modal)closeModal()}); addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
 root.querySelectorAll('[data-asset]').forEach(a=>a.addEventListener('click',()=>{if(imgIn){imgIn.value=a.dataset.url||'';imgIn.dispatchEvent(new Event('input',{bubbles:true}));}closeModal();selectTab('media');}));
 search&&search.addEventListener('input',()=>{const q=search.value.toLowerCase().trim();root.querySelectorAll('[data-asset]').forEach(a=>{const hay=((a.dataset.label||'')+' '+(a.dataset.bucket||'')+' '+(a.dataset.url||'')).toLowerCase();a.style.display=!q||hay.includes(q)?'block':'none';});});
 root.querySelector('[data-clear-media]')?.addEventListener('click',()=>{if(imgIn){imgIn.value='';imgIn.dispatchEvent(new Event('input',{bubbles:true}));}});
 const yKey='feedEditorScroll:'+location.pathname;try{const y=sessionStorage.getItem(yKey);if(y){setTimeout(()=>scrollTo(0,parseInt(y,10)||0),50)}}catch(e){}addEventListener('beforeunload',()=>{try{sessionStorage.setItem(yKey,String(scrollY))}catch(e){}});
})();
</script>
</body>
</html>
